/** Spaces the user cannot see, and rows missing any of the three columns, are absent from the map. */
export const getSpaceInfoFromIds = async (
  client: DGSupabaseClient,
  spaceIds: number[],
): Promise<Map<number, SpaceInfo>> => {
  if (spaceIds.length === 0) {
    return new Map();
  }

  const { data, error } = await client
    .from("my_spaces")
    .select("id, name, url, platform")
    .in("id", spaceIds);

  if (error) {
    console.error("Error fetching spaces:", error);
    return new Map();
  }

  const spaceMap = new Map<number, SpaceInfo>();
  (data ?? []).forEach(({ id, name, url, platform }) => {
    if (id === null || name === null || url === null || platform === null) {
      return;
    }
    spaceMap.set(id, { name, url, platform });
  });

  return spaceMap;
};

export const fetchUserNames = async (
  plugin: DiscourseGraphPlugin,
  client: DGSupabaseClient,
) => {
  const result = await client
    .from("my_accounts")
  return Object.fromEntries(
    (request.data || []).map(({ id, account_local_id }) => [
      id!,
      account_local_id!,
    ]),
  );
};

export const getSpaceMap = async (
  client: DGSupabaseClient,
  spaceIds?: number[],
): Promise<Record<number, string>> => {
  let query = client.from("my_spaces").select("id, url");
  if (spaceIds !== undefined) query = query.in("id", [...spaceIds]);

  const { data, error } = await query;
  if (error) throw error;
  if (!data) throw new Error("Missing spaces");
  return Object.fromEntries(data.map(({ id, url }) => [id!, url!]));
};

const asSimpleLocalId = (
  rid: string | undefined,
  spaceUrl: string | undefined,
  optional?: boolean,
): string | undefined => {
  if (rid === undefined) return undefined;
  if (!isRid(rid)) return rid;
  const { spaceUri, sourceLocalId } = ridToSpaceUriAndLocalId(rid);
  if (spaceUrl === spaceUri) return sourceLocalId;
  if (optional !== true) throw new Error("Unexpected spaceUri");
  return rid;
};

export const dbNodeSchemaToCrossApp = ({
  schema,
    ].filter((id) => id !== null),
  );
  if (currentSpace !== undefined) {
    currentSpaceId = currentSpace.id ?? currentSpaceId;
  } else if (currentSpaceId !== undefined)
    associatedSpaceIds.add(currentSpaceId);
  const spaces: SharedSpace[] = [];
  if (currentSpace !== undefined && currentSpaceId !== undefined) {
    spaces.push(currentSpace);
    associatedSpaceIds.delete(currentSpaceId);
  }
  if (associatedSpaceIds.size > 0) {
    const { data, error } = await client
      .from("my_spaces")
      .select(SPACE_COLUMNS)
      .in("id", [...associatedSpaceIds]);
    if (error) throw error;
    spaces.push(...data);
  }
  return spaces;
};

const getSharedNodeRows = async ({
  client,
  currentSpaceId,
}: {
  client: DGSupabaseClient;
  currentSpaceId: number;
}): Promise<SharedNodeRows> => {
  const [conceptsResponse, directResponse, fullResponse] = await Promise.all([
    client
      .from("my_concepts")
      .select(CONCEPT_COLUMNS_WITH_SLOTS)
      .neq("space_id", currentSpaceId)
      .eq("is_schema", false)
      .eq("is_relation", false),
    client
      .from("my_contents")
      .select(DIRECT_CONTENT_COLUMNS)
      .neq("space_id", currentSpaceId)
      .eq("variant", "direct"),
    client
      .from("my_contents")
      .select(FULL_CONTENT_SUMMARY_COLUMNS)
      .neq("space_id", currentSpaceId)
      .eq("variant", "full"),
  ]);
  if (conceptsResponse.error) throw conceptsResponse.error;
  if (directResponse.error) throw directResponse.error;
  if (fullResponse.error) throw fullResponse.error;
  const spaces = await getAssociatedSpaces({
    client,
    concepts: conceptsResponse.data,
    currentSpaceId,
  });

  return {
    nodes: conceptsResponse.data,
    directContents: directResponse.data,
    fullContentSummaries: fullResponse.data,
    spaces,
  };
};

export const listGroupSharedNodes = async ({
  client,
  currentSpaceId,
}: {
  client: DGSupabaseClient;
  currentSpaceId: number;
}): Promise<SharedNode[]> => {
  const rows = await getSharedNodeRows({ client, currentSpaceId });
  return buildSharedNodes(rows);
};

export const getSharedNodeByRid = async ({
  client,
  rid,
}: {
  client: DGSupabaseClient;
  rid: string;
}): Promise<SharedNode | null> => {
  const { spaceUri, sourceLocalId } = ridToSpaceUriAndLocalId(rid);
  const spaceResponse = await client
    .from("my_spaces")
    .select(SPACE_COLUMNS)
    .eq("url", spaceUri)
    .maybeSingle();
  if (spaceResponse.error) throw spaceResponse.error;
  const space = spaceResponse.data;
  if (!space || typeof space.id !== "number") return null;

  const [conceptsResponse, directResponse, fullResponse] = await Promise.all([
    client
      .from("my_concepts")
      .select(CONCEPT_COLUMNS_WITH_SLOTS)
      .eq("space_id", space.id)
      .eq("source_local_id", sourceLocalId)
      .eq("is_schema", false)
      .eq("is_relation", false),
    client
      .from("my_contents")
      .select(DIRECT_CONTENT_COLUMNS)
      .eq("space_id", space.id)
      .eq("source_local_id", sourceLocalId)
      .eq("variant", "direct"),
    group_id
) REFERENCES auth.users (id) ON UPDATE CASCADE ON DELETE CASCADE;

REVOKE ALL ON TABLE public.group_membership FROM anon;
GRANT ALL ON TABLE public.group_membership TO authenticated;
GRANT ALL ON TABLE public.group_membership TO service_role;

CREATE OR REPLACE VIEW public.my_groups AS
SELECT id, split_part(email, '@', 1) AS name FROM auth.users
    JOIN public.group_membership ON (group_id = id)
WHERE member_id = auth.uid();

CREATE TYPE public.account_local_input AS (
    -- PlatformAccount columns
    name VARCHAR,
    account_local_id VARCHAR,
    -- local values
    email VARCHAR,
    email_trusted BOOLEAN,
    space_editor BOOLEAN,
    permissions public."SpaceAccessPermissions"

