/** Spaces the user cannot see, and rows missing any of the three columns, are absent from the map. */
export const getSpaceInfoFromIds = async (
  client: DGSupabaseClient,
  spaceIds: number[],
): Promise<Map<number, SpaceInfo>> => {
  if (spaceIds.length === 0) {
    return new Map();
  }

  const { data, error } = await client
    .from("my_spaces")
    .select("id, name, url, platform")
    .in("id", spaceIds);

  if (error) {
    console.error("Error fetching spaces:", error);
    return new Map();
  }

  const spaceMap = new Map<number, SpaceInfo>();
  (data ?? []).forEach(({ id, name, url, platform }) => {
    if (id === null || name === null || url === null || platform === null) {
      return;
    }
    spaceMap.set(id, { name, url, platform });
  });

  return spaceMap;
};

export const fetchUserNames = async (
  plugin: DiscourseGraphPlugin,
  client: DGSupabaseClient,
) => {
  const result = await client
    .from("my_accounts")
  return Object.fromEntries(
    (request.data || []).map(({ id, account_local_id }) => [
      id!,
      account_local_id!,
    ]),
  );
};

export const getSpaceMap = async (
  client: DGSupabaseClient,
  spaceIds?: number[],
): Promise<Record<number, string>> => {
  let query = client.from("my_spaces").select("id, url");
  if (spaceIds !== undefined) query = query.in("id", [...spaceIds]);

  const { data, error } = await query;
  if (error) throw error;
  if (!data) throw new Error("Missing spaces");
  return Object.fromEntries(data.map(({ id, url }) => [id!, url!]));
};

const asSimpleLocalId = (
  rid: string | undefined,
  spaceUrl: string | undefined,
  optional?: boolean,
): string | undefined => {
  if (rid === undefined) return undefined;
  if (!isRid(rid)) return rid;
  const { spaceUri, sourceLocalId } = ridToSpaceUriAndLocalId(rid);
  if (spaceUrl === spaceUri) return sourceLocalId;
  if (optional !== true) throw new Error("Unexpected spaceUri");
  return rid;
};

